Mono<Rate> fxRate(String pair) {
    return Mono.defer(() -> primary.rate(pair))
        .timeout(Duration.ofMillis(300))                          // TimeoutException: an ordinary error
        .retryWhen(Retry.backoff(3, Duration.ofMillis(100))       // jitter 0.5 by default
            .filter(e -> e instanceof IOException || e instanceof TimeoutException))
        .timeout(Duration.ofSeconds(1))                           // overall budget
        .onErrorResume(e -> Exceptions.isRetryExhausted(e) || e instanceof TimeoutException,
                       e -> fallback.rate(pair));                // exhausted: RetryExhaustedException
}

