fun <T> Flow<T>.myCatch(action: suspend FlowCollector<T>.(Throwable) -> Unit): Flow<T> = flow {
    var fromDownstream: Throwable? = null
    try {
        collect { value ->
            try { emit(value) }
            catch (e: Throwable) { fromDownstream = e; throw e }   // 1. remember what the collector threw
        }
    } catch (e: Throwable) {
        if (e === fromDownstream) throw e                         // 2. below the net
        if (e is CancellationException && !currentCoroutineContext().isActive) throw e   // 3. our job
        action(e)                                                 // 4. from upstream
    }
}
// Only the upstream withTimeout reaches action: it is a CancellationException, but our job is still active.

