// Closest Java equivalent: a push-style source and a Consumer, with the same three checks
static <T> void myCatch(Consumer<Consumer<T>> upstream, Consumer<T> downstream, Function<Throwable, T> action) {
    RuntimeException[] fromDownstream = {null};
    try {
        upstream.accept(v -> {
            try { downstream.accept(v); }
            catch (RuntimeException e) { fromDownstream[0] = e; throw e; }   // 1. remember what the consumer threw
        });
    } catch (RuntimeException e) {
        if (e == fromDownstream[0]) throw e;                                 // 2. below the net
        if (Thread.currentThread().isInterrupted()) throw e;                 // 3. our own task was cancelled
        downstream.accept(action.apply(e));                                  // 4. from upstream
    }
}

